-- 商品图片种子数据：让新环境跑完 init.sql 后直接带上商品图片。
-- 来源：项目演示库中的商品图，缩放为最长边 700 像素的 JPEG，并合成到 #f3f8f4 背景（与界面图片框同色，观感接近透明底）。
-- 按商品名称匹配，不依赖自增主键；可重复执行，不覆盖已经上传的图片。
-- 执行前请先选库：USE `virtual_campus`;

SET NAMES utf8mb4;

-- 东大纪念笔记本：32397 字节
INSERT INTO `tbl_product_image` (`product_id`, `mime_type`, `image_data`)
SELECT p.`product_id`, 'image/jpeg', 
FROM `tbl_product` p
WHERE p.`product_name` = '东大纪念笔记本'
  AND NOT EXISTS (SELECT 1 FROM `tbl_product_image` i WHERE i.`product_id` = p.`product_id`);

